.hero {
 @layer daisyui.l1.l2.l3 {
 @apply grid w-full place-items-center bg-cover bg-center;
 & > * {
 @apply col-start-1 row-start-1;
 }
 }
}
.hero-overlay {
 @layer daisyui.l1.l2.l3 {
 @apply bg-neutral/50 col-start-1 row-start-1 h-full w-full;
 }
}
.hero-content {
 @layer daisyui.l1.l2.l3 {
 @apply isolate flex max-w-[80rem] items-center justify-center gap-4 p-4;
 }
}

.card {
 @layer daisyui.l1.l2.l3 {
 @apply rounded-box relative flex flex-col;
 transition: outline 0.2s ease-in-out;
 outline: 2px solid #0000;
 outline-offset: 2px;
 &:focus-visible,
 &[aria-checked="true"],
 &:has(> :checked, > :is([type="checkbox"], [type="radio"]):focus-visible) {
 outline-color: currentColor;
 }
 &:has(> :checked:focus-visible),
 &[aria-checked="true"]:focus-visible,
 &[aria-checked="true"]:has(> :is([type="checkbox"], [type="radio"]):focus-visible) {
 outline-width: 4px;
 }
 &:has(> :is([type="checkbox"], [type="radio"])) {
 @apply cursor-pointer;
 user-select: none;
 }
 > :is([type="checkbox"], [type="radio"]) {
 @apply appearance-none;
 }
 }
 @layer daisyui.l1.l2.l3.l4 {
 figure:first-child {
 @apply overflow-hidden;
 border-start-start-radius: inherit;
 border-start-end-radius: inherit;
 border-end-start-radius: unset;
 border-end-end-radius: unset;
 }
 figure:last-child {
 @apply overflow-hidden;
 border-start-start-radius: unset;
 border-start-end-radius: unset;
 border-end-start-radius: inherit;
 border-end-end-radius: inherit;
 }
 figure {
 @apply flex items-center justify-center;
 }
 }
}
.card-border {
 @layer daisyui.l1.l2 {
 border: var(--border) solid var(--color-base-200);
 }
}
.card-dash {
 @layer daisyui.l1.l2 {
 border: var(--border) dashed var(--color-base-200);
 }
}
.image-full {
 @layer daisyui.l1.l2 {
 @apply grid;
 > * {
 @apply col-start-1 row-start-1;
 }
 > .card-body {
 @apply text-neutral-content relative;
 }
 :where(figure) {
 @apply overflow-hidden;
 border-radius: inherit;
 }
 > figure img {
 @apply h-full object-cover;
 filter: brightness(28%);
 }
 }
}
.card-title {
 @layer daisyui.l1.l2.l3 {
 @apply flex items-center gap-2;
 font-size: var(--cardtitle-fs, 1.125rem);
 font-weight: 600;
 }
}
.card-body {
 @layer daisyui.l1.l2.l3 {
 @apply flex flex-auto flex-col gap-2;
 padding: var(--card-p, 1.5rem);
 font-size: var(--card-fs, 0.875rem);
 }
 @layer daisyui.l1.l2.l3.l4 {
 p {
 @apply grow;
 }
 }
}
.card-actions {
 @layer daisyui.l1.l2.l3 {
 @apply flex flex-wrap items-start gap-2;
 }
}
.card-xs {
 @layer daisyui.l1.l2 {
 .card-body {
 --card-p: 0.5rem;
 --card-fs: 0.6875rem;
 }
 .card-title {
 --cardtitle-fs: 0.875rem;
 }
 }
}
.card-sm {
 @layer daisyui.l1.l2 {
 .card-body {
 --card-p: 1rem;
 --card-fs: 0.75rem;
 }
 .card-title {
 --cardtitle-fs: 1rem;
 }
 }
}
.card-md {
 @layer daisyui.l1.l2 {
 .card-body {
 --card-p: 1.5rem;
 --card-fs: 0.875rem;
 }
[trimmed]

.stats {
 @layer daisyui.l1.l2.l3 {
 @apply rounded-box relative inline-grid grid-flow-col overflow-x-auto;
 }
}
.stat {
 @layer daisyui.l1.l2.l3 {
 @apply inline-grid w-full gap-x-4 px-6 py-4;
 grid-template-columns: repeat(1, 1fr);
 &:not(:last-child) {
 border-inline-end: var(--border) dashed color-mix(in oklab, currentColor 10%, #0000);
 border-block-end: none;
 }
 }
}
.stat-figure {
 @layer daisyui.l1.l2.l3 {
 @apply col-start-2 row-span-3 row-start-1 place-self-center justify-self-end;
 }
}
.stat-title {
 @layer daisyui.l1.l2.l3 {
 @apply text-base-content/60 col-start-1 whitespace-nowrap;
 font-size: 0.75rem;
 }
}
.stat-value {
 @layer daisyui.l1.l2.l3 {
 @apply col-start-1 whitespace-nowrap;
 font-size: 2rem;
 font-weight: 800;
 }
}
.stat-desc {
 @layer daisyui.l1.l2.l3 {
 @apply text-base-content/60 col-start-1 whitespace-nowrap;
 font-size: 0.75rem;
 }
}
.stat-actions {
 @layer daisyui.l1.l2.l3 {
 @apply col-start-1 whitespace-nowrap;
 }
}
.stats-horizontal {
 @layer daisyui.l1.l2 {
 @apply grid-flow-col overflow-x-auto;
 .stat:not(:last-child) {
 border-inline-end: var(--border) dashed color-mix(in oklab, currentColor 10%, #0000);
 border-block-end: none;
 }
 }
}
.stats-vertical {
 @layer daisyui.l1.l2 {
 @apply grid-flow-row overflow-y-auto;
 .stat:not(:last-child) {
 border-inline-end: none;
 border-block-end: var(--border) dashed color-mix(in oklab, currentColor 10%, #0000);
 }
 }
}

.footer {
 @layer daisyui.l1.l2.l3 {
 @apply grid w-full grid-flow-row place-items-start gap-x-4 gap-y-10;
 font-size: 0.875rem;
 line-height: 1.25rem;
 & > *:not(script, style, template) {
 @apply grid place-items-start gap-2;
 }
 &.footer-center {
 @apply grid-flow-col-dense place-items-center text-center;
 & > *:not(script, style, template) {
 @apply place-items-center;
 }
 }
 }
}
.footer-title {
 @layer daisyui.l1.l2.l3 {
 @apply mb-2 uppercase opacity-60;
 font-weight: 600;
 }
}
.footer-horizontal {
 @layer daisyui.l1.l2 {
 @apply grid-flow-col;
 &.footer-center {
 @apply grid-flow-row-dense;
 }
 }
}
.footer-vertical {
 @layer daisyui.l1.l2 {
 @apply grid-flow-row;
 &.footer-center {
 @apply grid-flow-col-dense;
 }
 }
}

.navbar {
 @layer daisyui.l1.l2.l3 {
 @apply flex w-full items-center;
 padding: 0.5rem;
 min-height: 4rem;
 }
}
:where(.navbar) {
 @layer daisyui.l1.l2 {
 @apply relative;
 }
}
.navbar-start {
 @layer daisyui.l1.l2.l3 {
 @apply inline-flex items-center;
 width: 50%;
 justify-content: flex-start;
 }
}
.navbar-center {
 @layer daisyui.l1.l2.l3 {
 @apply inline-flex items-center;
 @apply shrink-0;
 }
}
.navbar-end {
 @layer daisyui.l1.l2.l3 {
 @apply inline-flex items-center;
 width: 50%;
 justify-content: flex-end;
 }
}
